solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int h = n / 3600;
        int m = (n % 3600) / 60;
        int s = n % 60;
        System.out.println(h);
        System.out.println(m);
        System.out.println(s);
    }
}

